import{_ as p,a0 as l,w as o,s as d,ao as h,I as t,x as a,a1 as e,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"在 Linux 上調整命令歷史 | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 上調整命令歷史 | LCTT (202009) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 上調整命令歷史 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 上調整命令歷史 | LCTT (202009) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202009/20200415 Tweaking history on Linux","title":"在 Linux 上調整命令歷史","tag":"202009","desc":""},"relativePath":"202009/20200415 Tweaking history on Linux.md","filePath":"[post].md"}'),r={name:"202009/20200415 Tweaking history on Linux.md"};function c(g,s,k,b,u,y){const i=l("Link");return o(),d("div",null,[s[15]||(s[15]=h(`<h1 id="在-linux-上調整命令歷史" tabindex="-1">在 Linux 上調整命令歷史 <a class="header-anchor" href="#在-linux-上調整命令歷史" aria-label="Permalink to “在 Linux 上調整命令歷史”">​</a></h1><blockquote><p>在 Linux 系統上，bash shell 的 history 命令可以方便地回顧和重用命令，但是你要控制它記住多少，忘記多少，有很多事情要做。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202009/08/232418c2121m2euw3aaw58.jpg" alt=""></p><p>Linux 系統中的 bash <code>history</code> 命令有助於記住你以前運行過的命令，並重復這些命令，而不必重新輸入。</p><p>如果可以的話，你肯定會很高興不用翻閲十幾頁的手冊，每過一會再次列出你的文件，而是通過輸入 <code>history</code> 查看以前運行的命令。在這篇文章中，我們將探討如何讓 <code>history</code> 命令記住你希望它記住的內容，並忘記那些可能沒有什麼“歷史價值”的命令。</p><h3 id="查看你的命令歷史" tabindex="-1">查看你的命令歷史 <a class="header-anchor" href="#查看你的命令歷史" aria-label="Permalink to “查看你的命令歷史”">​</a></h3><p>要查看以前運行過的命令，你只需輸入 <code>history</code>。你可能會看到一長串命令。記憶的命令數量取決於在 <code>~/.bashrc</code> 文件中設置的名為 <code>$HISTSIZE</code> 的環境變量，但是如果你想保存更多或更少的命令，你可以根據你的需要改變這個設置。</p><p>要查看歷史記錄，請使用 <code>history</code> 命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ history</span></span>
<span class="line"><span>209 uname -v</span></span>
<span class="line"><span>210 date</span></span>
<span class="line"><span>211 man chage</span></span>
<span class="line"><span>...</span></span></code></pre></div><p>要查看將顯示的最大命令數量：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo $HISTSIZE</span></span>
<span class="line"><span>500</span></span></code></pre></div><p>你可以通過運行這樣的命令來改變 <code>$HISTSIZE</code> 並使之永久化：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ export HISTSIZE=1000</span></span>
<span class="line"><span>$ echo &quot;HISTSIZE=1000&quot; &gt;&gt; ~/.bashrc</span></span></code></pre></div><p>在為你保留多少歷史記錄和當你輸入 <code>history</code> 時顯示多少歷史記錄之間也有區別。<code>$HISTSIZE</code> 變量控制顯示多少歷史記錄，而 <code>$HISTFILESIZE</code> 變量控制在你的 <code>.bash_history</code> 文件中保留多少命令。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo $HISTSIZE</span></span>
<span class="line"><span>1000</span></span>
<span class="line"><span>$ echo $HISTFILESIZE</span></span>
<span class="line"><span>2000</span></span></code></pre></div><p>你可以通過計算歷史文件中的行數來驗證第二個變量：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ wc -l .bash_history</span></span>
<span class="line"><span>2000 .bash_history</span></span></code></pre></div><p>需要注意的是，在登錄會話中輸入的命令在註銷前不會被添加到你的 <code>.bash_history</code> 文件中，儘管它們會立即顯示在 <code>history</code> 命令輸出中。</p><h3 id="使用歷史" tabindex="-1">使用歷史 <a class="header-anchor" href="#使用歷史" aria-label="Permalink to “使用歷史”">​</a></h3><p>有三種方法可以重發你在 <code>history</code> 中發現的命令。最簡單的方法，特別是當你想重用的命令是最近運行的時候，通常是輸入一個 <code>!</code> 後面跟上命令中足夠多的首字母來唯一地識別它。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ !u</span></span>
<span class="line"><span>uname -v</span></span>
<span class="line"><span>#37-Ubuntu SMP Thu Mar 26 20:41:27 UTC 2020</span></span></code></pre></div><p>另一種簡單的重複命令的方法是，只需按上箭頭鍵，直到顯示了該命令，然後按回車鍵。</p><p>另外，如果你運行 <code>history</code> 命令，並看到你想重新運行的命令被列出，你可以輸入一個 <code>!</code> 後面跟着命令左邊顯示的序號。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ !209</span></span>
<span class="line"><span>uname -v</span></span>
<span class="line"><span>#37-Ubuntu SMP Thu Mar 26 20:41:27 UTC 2020</span></span></code></pre></div><h3 id="隱藏曆史" tabindex="-1">隱藏曆史 <a class="header-anchor" href="#隱藏曆史" aria-label="Permalink to “隱藏曆史”">​</a></h3><p>如果你想在一段時間內停止記錄命令，你可以使用這個命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ set +o history</span></span></code></pre></div><p>當你輸入 <code>history</code> 時，你輸入的命令不會顯示出來，當你退出會話或退出終端時，它們也不會被添加到你的 <code>.bash_history</code> 文件中。</p><p>要取消這個設置，使用 <code>set -o history</code>。</p><p>要使它永久化，你可以把它添加到你的 <code>.bashrc</code> 文件中，儘管不使用命令歷史記錄通常不是一個好主意。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo &#39;set +o history&#39; &gt;&gt; ~/.bashrc</span></span></code></pre></div><p>要暫時清除歷史記錄，這樣在輸入 <code>history</code> 時只顯示之後輸入的命令，可以使用 <code>history -c</code>（清除）命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ history | tail -3</span></span>
<span class="line"><span>209 uname -v</span></span>
<span class="line"><span>210 date</span></span>
<span class="line"><span>211 man chage</span></span>
<span class="line"><span>$ history -c</span></span>
<span class="line"><span>$ history</span></span>
<span class="line"><span>1  history</span></span></code></pre></div><p>注意：在輸入 <code>history -c</code> 後輸入的命令不會被添加到 <code>.bash_history</code> 文件中。</p><h3 id="控制歷史" tabindex="-1">控制歷史 <a class="header-anchor" href="#控制歷史" aria-label="Permalink to “控制歷史”">​</a></h3><p>許多系統上的 <code>history</code> 命令的設置會默認包括一個名為 <code>$HISTCONTROL</code> 的變量，以確保即使你連續運行同一命令七次，也只會被記住一次。它還可以確保你在首先輸入一個或多個空格後跟着的命令將從你的命令歷史記錄中忽略。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ grep HISTCONTROL .bashrc</span></span>
<span class="line"><span>HISTCONTROL=ignoreboth</span></span></code></pre></div><p><code>ignoreboth</code> 的意思是“忽略重複的命令和以空格開頭的命令”。例如，如果你輸入這些命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo try this</span></span>
<span class="line"><span>$ date</span></span>
<span class="line"><span>$ date</span></span>
<span class="line"><span>$ date</span></span>
<span class="line"><span>$   pwd</span></span>
<span class="line"><span>$ history</span></span></code></pre></div><p>你的 <code>history</code> 命令應該像這樣報告：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ history</span></span>
<span class="line"><span>$ echo try this</span></span>
<span class="line"><span>$ date</span></span>
<span class="line"><span>$ history</span></span></code></pre></div><p>請注意，連續的 <code>date</code> 命令被縮減為一條，以空格縮進的命令被省略。</p><h3 id="忽略歷史" tabindex="-1">忽略歷史 <a class="header-anchor" href="#忽略歷史" aria-label="Permalink to “忽略歷史”">​</a></h3><p>要忽略某些命令，使它們在你輸入 <code>history</code> 時不會出現，也不會被添加到你的 <code>.bash_history</code> 文件中，可以使用 <code>$HISTIGNORE</code> 設置。例如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ export HISTIGNORE=”history:cd:exit:ls:pwd:man”</span></span></code></pre></div><p>這個設置將導致所有的 <code>history</code>、<code>cd</code>、<code>exit</code>、<code>ls</code>、<code>pwd</code> 和 <code>man</code> 命令從你的 <code>history</code> 命令的輸出和 <code>.bash_history</code> 文件中被忽略。</p><p>如果你想把這個設置變成永久性的，你必須把它添加到你的 <code>.bashrc</code> 文件中。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo &#39;HISTIGNORE=&quot;history:cd:exit:ls:pwd:man&quot;&#39; &gt;&gt; .bashrc</span></span></code></pre></div><p>這個設置只是意味着當你回看以前運行的命令時，列表不會被你在查看命令歷史記錄時不想看到的命令所幹擾。</p><h3 id="記住、忽略和忘記過去的命令" tabindex="-1">記住、忽略和忘記過去的命令 <a class="header-anchor" href="#記住、忽略和忘記過去的命令" aria-label="Permalink to “記住、忽略和忘記過去的命令”">​</a></h3><p>命令歷史記錄很有用，因為它可以幫助你記住最近使用過的命令，並提醒你最近所做的更改。它還可以讓你更容易地重新運行命令，特別是那些有一串參數但你不一定想重新創建的命令。定製你的歷史設置可以讓你對命令歷史的使用變得更容易，更有效率。</p><hr>`,52)),t("p",null,[s[1]||(s[1]=a("via: ",-1)),e(i,{href:"https://www.networkworld.com/article/3537214/tweaking-history-on-linux.html"},{default:n(()=>[...s[0]||(s[0]=[a("https://www.networkworld.com/article/3537214/tweaking-history-on-linux.html",-1)])]),_:1})]),t("p",null,[s[6]||(s[6]=a("作者：",-1)),e(i,{href:"https://www.networkworld.com/author/Sandra-Henry_Stocker/"},{default:n(()=>[...s[2]||(s[2]=[a("Sandra Henry-Stocker",-1)])]),_:1}),s[7]||(s[7]=a(" 選題：",-1)),e(i,{href:"https://github.com/lujun9972"},{default:n(()=>[...s[3]||(s[3]=[a("lujun9972",-1)])]),_:1}),s[8]||(s[8]=a(" 譯者：",-1)),e(i,{href:"https://github.com/wxy"},{default:n(()=>[...s[4]||(s[4]=[a("wxy",-1)])]),_:1}),s[9]||(s[9]=a(" 校對：",-1)),e(i,{href:"https://github.com/wxy"},{default:n(()=>[...s[5]||(s[5]=[a("wxy",-1)])]),_:1})]),t("p",null,[s[12]||(s[12]=a("本文由 ",-1)),e(i,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...s[10]||(s[10]=[a("LCTT",-1)])]),_:1}),s[13]||(s[13]=a(" 原創編譯，",-1)),e(i,{href:"https://linux.cn/"},{default:n(()=>[...s[11]||(s[11]=[a("Linux中國",-1)])]),_:1}),s[14]||(s[14]=a(" 榮譽推出",-1))])])}const C=p(r,[["render",c]]);export{x as __pageData,C as default};
